"""Checks how your tests are organized. Do not edit this file.

Tests are code too: pytest can list them without running them (--collect-only).
That is what this check does.
"""

import os
import subprocess
import sys
from pathlib import Path

LAB = Path(__file__).resolve().parent.parent
RULES = {"too-short", "no-digit", "no-upper", "no-lower", "whitespace", "common"}


def collect() -> list[str]:
    env = {**os.environ, "PYTHONIOENCODING": "utf-8"}
    env.pop("PASSWORDS_MUTANT", None)
    result = subprocess.run(
        [sys.executable, "-m", "pytest", "tests/test_policy.py", "--collect-only", "-q", "-p", "no:cacheprovider"],
        cwd=LAB, env=env, capture_output=True, text=True, encoding="utf-8", errors="replace",
    )
    return [line for line in result.stdout.splitlines() if "::" in line]


# Task 1


def test_rules_are_one_parametrized_test_with_readable_ids():
    ids = {line.split("[", 1)[1].rstrip("]") for line in collect() if "::test_each_rule[" in line}
    missing = RULES - ids
    assert not missing, f"test_each_rule needs one case per rule with these ids: {sorted(missing)}"


def test_the_copied_tests_are_gone():
    names = {line.split("::", 1)[1] for line in collect()}
    left = {"test_too_short", "test_no_digit", "test_no_upper"} & names
    assert not left, f"Remove the tests that test_each_rule replaces: {sorted(left)}"
